CREATE EXTENSION IF NOT EXISTS unaccent;
DO $$ DECLARE missing text; BEGIN
  SELECT string_agg(n, ', ') INTO missing FROM unnest(ARRAY['Timothy Moore','Reggina Sandoval','Luis Abad','Yessenia Moran','Navvad Owusu','Tanya Bedoya','Sarah Mora','Arelis Acosta','Eduardo Herrera','Monique Luque','Jose De Hermoso','Domingo Cruz','Eddy Cedeño','Daniel Escruceria','Juan Fonseca','Jennette Torrano','Elizabeth Mootoo','Jose Navarro','Favian Fortune','Lilian Barría','Juan Lezcano','Ulla Hees','Jeanine Puyol','Charis Dixon','Alisha Dua','Gabriela Jaen','Gabriel Chu','Alanis Chena','Osvaldo Medina','Gisselle Vanessa Ramos Pérez de Brown','Charles Bush','Aleka Papatsoris','Karhid Arevalo','Carlos Aloma','Winston Carrillo','Eder Quintero','Isaac Chung','Jean Pierre Montfort','Maria Alejandra De Urriola','Cemiriamiz Iglesias','Edwin Broce','Euclides Gonzalez','Michael Antonio Jones Roye','Rocio Pretto','Nichole Harris','Natalia Esquivel','Veronica Vasquez','Diana Rodriguez','Juan Molina','Samuel Duarte','Ángela Rodgers']) AS n WHERE NOT EXISTS (SELECT 1 FROM employees WHERE lower(unaccent(display_name)) = lower(unaccent(n)));
  IF missing IS NOT NULL THEN RAISE EXCEPTION 'Unknown employees in sheet: %', missing; END IF;
END $$;

